{"witnessCode": "import { describe, it } from 'node:test';import assert from 'node:assert/strict';import normalizeUrl from '../index.js';

describe('query parameter double-encoding regression', () => {
  it('should not double-encode percent-encoded spaces when sortQueryParameters is true', () => {
    const input = 'http://example.com/path/?q=hello%2520world';
    const expected = 'http://example.com/path/?q=hello%20world';
    const actual = normalizeUrl(input, { removeTrailingSlash: false });
    assert.strictEqual(actual, expected);
  });
});"}
